function SkillCardsNodeBase:Awake()
    local goCardIcon = self.controller.transform:Find("SkillIcon")
    if not IsNull(goCardIcon) then
        self.cardIcon = IsNull(goCardIcon:GetComponent(typeof(Image))) 
                and goCardIcon:GetComponent(typeof(RawImage)) or goCardIcon:GetComponent(typeof(Image))
    end
    local goCardTypeIcon = self.controller.transform:Find("SkillType")
    if not IsNull(goCardTypeIcon) then
        self.cardTypeIcon = IsNull(goCardTypeIcon:GetComponent(typeof(Image))) 
                and goCardTypeIcon:GetComponent(typeof(RawImage)) or goCardTypeIcon:GetComponent(typeof(Image))
    end
    local goCardFrame = self.controller.transform:Find("CardNodeFrame")
    if not IsNull(goCardFrame) then
        self.cardFrame = IsNull(goCardFrame:GetComponent(typeof(Image)))
                and goCardFrame:GetComponent(typeof(RawImage)) or goCardFrame:GetComponent(typeof(Image))
    end
    local LevelRoot = self.controller.transform:Find("Level")
    if not IsNull(LevelRoot) then
        self.levelRoot = LevelRoot.gameObject
    end
    local txtLv = self.controller.transform:Find("Level/TextNumber")
    if not IsNull(txtLv) then
        self.cardLvTxt = txtLv.gameObject:GetComponent(typeof(CS.TMPro.TextMeshProUGUI))
    end
    KTool.SetActive(self.levelRoot, false)
end

function SkillCardsNodeBase:OnDestroy()
    self.controller = nil
    self:Delete()
    self = nil
end

---SetSkillCardInfo
---设置技能卡数据
---@param cardData SkillDataVo
function SkillCardsNodeBase:SetSkillCardInfo(cardData)
    self.skillCardData = cardData
    self.skillCardSkillId = checkInt(cardData.skillId)
    self.skillCardStarLevel = checkInt(cardData.star)
    self.attributeType = checkInt(cardData.attributeType)
    self.cardSkillLv = checkInt(cardData.skillLv)
    self.skillIndex = cardData.skillIndex
    local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(self.skillCardSkillId, 1)
    if not IsNull(skillCardVo) then
        self.skillType = skillCardVo.skillType
        self.isSPSkill = checkInt(self.skillType) == 3
    end
    if not IsNull(self.skillCardSkillId) then
        local showLabel = UIBattlingTools.GetSkillCardInfoByTwoParam(self.skillCardSkillId, self.skillCardStarLevel).showLabel
        self.cardType = UICommonUtils:GetSkillShowLabelWithStar(showLabel, self.skillCardStarLevel)
    end
    self.isAoe = checkBool(checkNumber(skillCardVo.isAoe) > 0)
end

---ReloadCardInfo
---设置技能卡资源引用
function SkillCardsNodeBase:ReloadCardInfo()
    self:SetSkillCardIcon()
    self:SetSkillCardTypeIcon()
    self:SetSkillCardFrame()
    self:SetSkillCardLv()
end

function SkillCardsNodeBase:SetSkillCardLv()
    if IsNull(self.levelRoot) then return end
    KTool.SetActive(self.levelRoot, self.isSPSkill)
    if self.isSPSkill then
        local showLv = CardConfMgr:GetInstance():GetFinalSkillDisplayLevel(self.cardSkillLv)
        self.cardLvTxt.text = string.format("<size=30>Lv</size>.%02d", showLv)
    end
end

function SkillCardsNodeBase:SetSkillCardFrame()
    self:GetAttributeColor()
    local pathFramePart = Path.GetFileNameWithoutExtension(self.isSPSkill and Constants.SkillCardFrame.SP or Constants.SkillCardFrame.Common)
    local pathFrame = string.format("UIAtlas/Cultivate/AttributeIcon/%s.png",pathFramePart) 
    self.cardFrame.gameObject:EnsureComponent(typeof(ImageAlterable)):LoadSprite(pathFrame)
    self.cardFrame.color = CS.Engine.Lib.XLuaUtils.HexToColor(self.skillCardTypeIconColor)
end

---SetSkillCardIcon
---显示 技能Icon
function SkillCardsNodeBase:SetSkillCardIcon()
    if IsNull(self.skillCardSkillId) then return end
    self:GetSkillCardIconPath()
    self.cardIcon.gameObject:GetComponent(typeof(ImageAlterable)):LoadSprite(self.skillCardImgPath)
end

---GetSkillCardIconPath
---获取技能卡 Icon 图片路径
function SkillCardsNodeBase:GetSkillCardIconPath()
    if IsNull(self.skillCardSkillId) or IsNull(self.skillCardStarLevel) then return end
    local listSkillCardImgPath = UIBattlingTools.GetSkillCardInfoByTwoParam(self.skillCardSkillId, self.skillCardStarLevel).skillIconPath -- 人物技能卡 1,2,3 星卡面不同
    self.skillCardImgPath = listSkillCardImgPath[1] -- 技能卡卡面 Icon 的图片路径
end

---SetSkillCardTypeIcon
---显示 技能类型
function SkillCardsNodeBase:SetSkillCardTypeIcon()
    self:GetSkillTypeImg()
    if not IsNull(self.skillCardTypeIconPath) then
        KTool.SetActive(self.cardTypeIcon.gameObject, true)
        local imageAlterableComp = self.cardTypeIcon.gameObject:GetComponent(typeof(ImageAlterable))
        imageAlterableComp:LoadSprite(self.skillCardTypeIconPath)
    else
        KTool.SetActive(self.cardTypeIcon.gameObject, false)
    end
end

---GetSkillTypeImg
---技能类型 资源路径
function SkillCardsNodeBase:GetSkillTypeImg()
    self.skillCardTypeIconPath = UICommonUtils:GetCardSkillAttrIcon(self.cardType, self.attributeType)
end

function SkillCardsNodeBase:GetAttributeColor()
    self.skillCardTypeIconColor = self.isSPSkill and "ffffff"
            or Constants.SkillCardColor[string.format("%d_%d",checkNumber(self.attributeType), 1)]
end

return SkillCardsNodeBase
